CustomField.formula:
IF(NOT(AND( carsensor_publication__c ,  goonet_publication__c ,  googlemap_publication__c ,  autoserver_publication__c ,  aucnet_publication__c ,  quickquick_publication__c )), 
IF(NOT(ISBLANK(publication_cancel_request_date__c)), "掲載取り下げ",
    IF(NOT(ISBLANK(change_amount_request_date__c)), "掲載金額変更",
        IF(NOT(ISBLANK( publication_request_date__c )), "新規掲載", "")
    )
), "")
